{"command": "cat << 'EOF' > /workdir/solve_connected.py
import time
from collections import deque

# Read grid
with open('/workdir/data/input.txt', 'r') as f:
    lines = f.read().strip().split('\n')

grid = [line.split() for line in lines]
rows, cols = len(grid), len(grid[0])

# Collect X cells
x_cells = []
for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 'X':
            x_cells.append((r, c))

n = len(x_cells)
print(f"Grid: {rows}x{cols}, X cells: {n}")

# Precompute neighbors
neighbors_raw = {}
for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 'X':
            neighs = []
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 'X':
                    neighs.append((nr, nc))
            neighbors_raw[(r,c)] = neighs

idx_map = {cell: i for i, cell in enumerate(x_cells)}
cell_from_idx = list(x_cells)

# Connectivity check function - optimized
def check_connectivity(visited_mask):
    """Check if all unvisited cells form a single connected component using BFS"""
    # Count unvisited
    unvisited = []
    for i in range(n):
        if not (visited_mask & (1 << i)):
            unvisited.append(i)

    if len(unvisited) == 0:
        return True
    if len(unvisited) == 1:
        return True  # Only one cell left, trivially connected

    # BFS from first unvisited
    start = unvisited[0]
    visited_bfs = {start}
    queue = deque([start])

    while queue:
        u = queue.popleft()
        r, c = cell_from_idx[u]
        for v in neighbors_raw[(r,c)]:
            v_idx = idx_map[v]
            if v_idx not in visited_bfs and not (visited_mask & (1 << v_idx)):
                visited_bfs.add(v_idx)
                queue.append(v_idx)

    return len(visited_bfs) == len(unvisited)

# DFS with connectivity pruning
unique_count = 0

def dfs(curr_idx, depth, visited_mask, start_idx):
    global unique_count
    if depth == n:
        # Found complete path
        if start_idx <= curr_idx:
            unique_count += 1
        return

    # Pruning: check connectivity of remaining unvisited cells
    if not check_connectivity(visited_mask):
        return

    curr_cell = cell_from_idx[curr_idx]
    for nxt in neighbors_raw[curr_cell]:
        nxt_idx = idx_map[nxt]
        if not (visited_mask & (1 << nxt_idx)):
            visited_mask |= (1 << nxt_idx)
            dfs(nxt_idx, depth + 1, visited_mask, start_idx)
            visited_mask &= ~(1 << nxt_idx)

# Time the full computation
start_time = time.time()

# Start DFS from each cell
for start_idx in range(n):
    visited_mask = 1 << start_idx
    dfs(start_idx, 1, visited_mask, start_idx)

elapsed = time.time() - start_time
print(f"Total unique Hamiltonian paths: {unique_count}")
print(f"Time elapsed: {elapsed:.2f}s")

# Write result
with open('/workdir/sol.txt', 'w') as f:
    f.write(str(unique_count))
print(f"Result: {unique_count}")
